def get_sampling(im):
    if not isinstance(im, JpegImageFile) or im.layers in (1, 4):
        return -1
    sampling = im.layer[0][slice(1, 3, None)] + im.layer[1][slice(1, 3, None)] + im.layer[2][slice(1, 3, None)]
    return samplings.get(sampling, -1)


