class BitStream:
    
    def __init__(self, fp):
        self.fp = fp
        self.bits = 0
        self.bitbuffer = 0

    
    def next(self):
        return i8(self.fp.read(1))

    
    def peek(self, bits):
        while self.bits < bits:
            self.bitbuffer = (self.bitbuffer << 8) + self.next()
            self.bits += 8
