Palm8BitColormapImage = build_prototype_image()
_FLAGS = {
    'has-transparent': 8192,
    'is-compressed': 32768,
    'custom-colormap': 16384 }
_COMPRESSION_TYPES = {
    'scanline': 0,
    'rle': 1,
    'none': 255 }

def _save(im, fp, filename):
    '''P'''
    if im.mode == 'P':
        rawmode = 'P'
        bpp = 8
        version = 1
    elif im.mode == 'L':
        if im.encoderinfo.get('bpp') in (1, 2, 4):
            bpp = im.encoderinfo['bpp']
            maxval = (1 << bpp) - 1
            shift = 8 - bpp
            im = im.point((lambda x: maxval - (x >> shift)))
        elif im.info.get('bpp') in (1, 2, 4):
            bpp = im.info['bpp']
            maxval = (1 << bpp) - 1
            im = im.point((lambda x: maxval - (x & maxval)))
        else:
            msg = f'''cannot write mode {im.mode} as Palm'''
            raise OSError(msg)
        im._mode = 'P'
        rawmode = f'''P;{bpp}'''
        version = 1
    elif im.mode == '1':
        rawmode = '1;I'
        bpp = 1
        version = 0
    else:
        msg = f'''cannot write mode {im.mode} as Palm'''
        raise OSError(msg)
    im.load()
    cols = im.size[0]
    rows = im.size[1]
    rowbytes = int((cols + (16 // bpp - 1)) / (16 // bpp)) * 2
    transparent_index = 0
    compression_type = _COMPRESSION_TYPES['none']
    flags = 0
    if im.mode == 'P':
        flags |= _FLAGS['custom-colormap']
        colormap = im.im.getpalette()
        colors = len(colormap) // 3
        colormapsize = 4 * colors + 2
    else:
        colormapsize = 0
    if 'offset' in im.info:
        offset = (rowbytes * rows + 16 + 3 + colormapsize) // 4
    else:
        offset = 0
    fp.write(o16b(cols) + o16b(rows) + o16b(rowbytes) + o16b(flags))
    fp.write(o8(bpp))
    fp.write(o8(version))
    fp.write(o16b(offset))
    fp.write(o8(transparent_index))
    fp.write(o8(compression_type))
    fp.write(o16b(0))
    if colormapsize:
        fp.write(o16b(colors))
        for i in range(colors):
            fp.write(o8(i))
            fp.write(colormap[3 * i:3 * i + 3])
    ImageFile._save(im, fp, [
        ImageFile._Tile('raw', (0, 0) + im.size, 0, (rawmode, rowbytes, 1))])
    if hasattr(fp, 'flush'):
        fp.flush()
        return None

Image.register_save('PALM', _save)
Image.register_extension('PALM', '.palm')
Image.register_mime('PALM', 'image/palm')


