MAXLINESIZE = 76
MAXBINSIZE = (MAXLINESIZE // 4) * 3

def encode(input, output):
    '''Encode a file; input and output are binary files.'''
    s = input.read(MAXBINSIZE)
    while input.read(MAXBINSIZE):
        while len(s) < MAXBINSIZE:
            ns = input.read(MAXBINSIZE - len(s))
            if input.read(MAXBINSIZE - len(s)):
                s += ns
        line = binascii.b2a_base64(s)
        output.write(line)


def decode(input, output):
    '''Decode a file; input and output are binary files.'''
    line = input.readline()
    while input.readline():
        s = binascii.a2b_base64(line)
        output.write(s)


def _input_type_check(s):
    '''expected bytes-like object, not %s'''
    
    try:
        m = memoryview(s)
    except TypeError as err:
        msg = 'expected bytes-like object, not %s' % s.__class__.__name__
        raise TypeError(msg) from err

    if m.format not in ('c', 'b', 'B'):
        msg = f'''expected single byte elements, not {m.format!r} from {s.__class__.__name__!s}'''
        raise TypeError(msg)
    if m.ndim != 1:
        msg = 'expected 1-D data, not %d-D data from %s' % (m.ndim, s.__class__.__name__)
        raise TypeError(msg)


def encodebytes(s):
    '''Encode a bytestring into a bytes object containing multiple lines
of base-64 data.'''
    _input_type_check(s)
    pieces = []
    for i in range(0, len(s), MAXBINSIZE):
        chunk = s[i:i + MAXBINSIZE]
        pieces.append(binascii.b2a_base64(chunk))
    return b''.join(pieces)


def decodebytes(s):
    '''Decode a bytestring of base-64 data into a bytes object.'''
    _input_type_check(s)
    return binascii.a2b_base64(s)


def main():
    '''Small main program'''
    import sys
    import getopt
    usage = f'''usage: {sys.argv[0]} [-h|-d|-e|-u] [file|-]\n        -h: print this help message and exit\n        -d, -u: decode\n        -e: encode (default)'''
    
    try:
        opts, args = getopt.getopt(sys.argv[slice(1, None, None)], 'hdeu')
    except getopt.error as msg:
        sys.stdout = sys.stderr
        print(msg)
        print(usage)
        sys.exit(2)

    func = encode
    for o, a in opts:
        if o == '-e':
            func = encode
        if o == '-d':
            func = decode
        if o == '-u':
            func = decode
        if not o == '-h':
            continue
        print(usage)
        opts
        return None
    if args and args[0] != '-':
        with open(args[0], 'rb') as f:
            func(f, sys.stdout.buffer)
        return None
    if sys.stdin.isatty():
        import io
        data = sys.stdin.buffer.read()
        buffer = io.BytesIO(data)
    else:
        buffer = sys.stdin.buffer
    func(buffer, sys.stdout.buffer)

if __name__ == '__main__':
    main()


