        s = []
        fmt = '            <tr><td class="diff_next"%s>%s</td>%s<td class="diff_next">%s</td>%s</tr>\n'
        for i in range(len(flaglist)):
            while flaglist[i]:
                if i > 0:
                    s.append('        </tbody>        \n        <tbody>\n')
                    continue
            s.append(fmt % (next_id[i], next_href[i], fromlist[i], next_href[i], tolist[i]))
