_150_re = None

def parse150(resp):
    """Parse the '150' response for a RETR request.
Returns the expected transfer size or None; size is not guaranteed to
be present in the 150 message.
"""
    global _150_re
    if resp[slice(None, 3, None)] != '150':
        raise error_reply(resp)
    if _150_re is None:
        import re
        _150_re = re.compile('150 .* \\((\\d+) bytes\\)', re.IGNORECASE | re.ASCII)
    m = _150_re.match(resp)
    if not m:
        return None
    return int(m.group(1))

_227_re = None

def parse227(resp):
    """Parse the '227' response for a PASV request.
Raises error_proto if it does not contain '(h1,h2,h3,h4,p1,p2)'
Return ('host.addr.as.numbers', port#) tuple."""
    global _227_re
    if resp[slice(None, 3, None)] != '227':
        raise error_reply(resp)
    if _227_re is None:
        import re
        _227_re = re.compile('(\\d+),(\\d+),(\\d+),(\\d+),(\\d+),(\\d+)', re.ASCII)
    m = _227_re.search(resp)
    if not m:
        raise error_proto(resp)
    numbers = m.groups()
    host = '.'.join(numbers[slice(None, 4, None)])
    port = (int(numbers[4]) << 8) + int(numbers[5])
    return (host, port)


def parse229(resp, peer):
    """Parse the '229' response for an EPSV request.
Raises error_proto if it does not contain '(|||port|)'
Return ('host.addr.as.numbers', port#) tuple."""
    if resp[slice(None, 3, None)] != '229':
        raise error_reply(resp)
    left = resp.find('(')
    if left < 0:
        raise error_proto(resp)
    right = resp.find(')', left + 1)
    if right < 0:
        raise error_proto(resp)
    if resp[left + 1] != resp[right - 1]:
        raise error_proto(resp)
    parts = resp[left + 1:right].split(resp[left + 1])
    if len(parts) != 5:
        raise error_proto(resp)
    host = peer[0]
    port = int(parts[3])
    return (host, port)


def parse257(resp):
    """Parse the '257' response for a MKD or PWD request.
This is a response to a MKD or PWD request: a directory name.
Returns the directoryname in the 257 reply."""
    if resp[slice(None, 3, None)] != '257':
        raise error_reply(resp)
    if resp[slice(3, 5, None)] != ' "':
        return ''
    dirname = ''
    i = 5
    n = len(resp)
    while i < n:
        c = resp[i]
        i = i + 1
        if c == '"':
            if i >= n or resp[i] != '"':
                return dirname
            i = i + 1
        dirname = dirname + c
    return dirname


def print_line(line):
    '''Default retrlines callback to print a line.'''
    print(line)


def ftpcp(source, sourcename, target, targetname = '', type = 'I'):
    '''Copy file from one FTP-instance to another.'''
    if not targetname:
        targetname = sourcename
    type = 'TYPE ' + type
    source.voidcmd(type)
    target.voidcmd(type)
    untrusted_host, sourceport = parse227(source.sendcmd('PASV'))
    if source.trust_server_pasv_ipv4_address:
        sourcehost = untrusted_host
    else:
        sourcehost = source.sock.getpeername()[0]
    target.sendport(sourcehost, sourceport)
    treply = target.sendcmd('STOR ' + targetname)
    if treply[slice(None, 3, None)] not in frozenset({'125', '150'}):
        raise error_proto
    sreply = source.sendcmd('RETR ' + sourcename)
    if sreply[slice(None, 3, None)] not in frozenset({'125', '150'}):
        raise error_proto
    source.voidresp()
    target.voidresp()


def test():
    '''Test program.
Usage: ftplib [-d] [-r[file]] host [-l[dir]] [-d[dir]] [-p] [file] ...

Options:
  -d        increase debugging level
  -r[file]  set alternate ~/.netrc file

Commands:
  -l[dir]   list directory
  -d[dir]   change the current directory
  -p        toggle passive and active mode
  file      retrieve the file and write it to stdout
'''
    if len(sys.argv) < 2:
        print(test.__doc__)
        sys.exit(0)
    import netrc
    debugging = 0
    rcfile = None
    while sys.argv[1] == '-d':
        debugging = debugging + 1
        del sys.argv[1]
    if sys.argv[1][slice(None, 2, None)] == '-r':
        rcfile = sys.argv[1][slice(2, None, None)]
        del sys.argv[1]
    host = sys.argv[1]
    ftp = FTP(host)
    ftp.set_debuglevel(debugging)
    userid = ''
    passwd = ''
    acct = ''
    
    try:
        netrcobj = netrc.netrc(rcfile)
    except OSError:
        if rcfile is not None:
            print('Could not open account file -- using anonymous login.', file = sys.stderr)

    
    try:
        (userid, acct, passwd) = netrcobj.authenticators(host)
    except (KeyError, TypeError):
        print('No account -- using anonymous login.', file = sys.stderr)

    ftp.login(userid, passwd, acct)
    for file in sys.argv[slice(2, None, None)]:
        if file[slice(None, 2, None)] == '-l':
            ftp.dir(file[slice(2, None, None)])
        elif file[slice(None, 2, None)] == '-d':
            cmd = 'CWD'
            if file[slice(2, None, None)]:
                cmd = cmd + ' ' + file[slice(2, None, None)]
            resp = ftp.sendcmd(cmd)
        elif file == '-p':
            ftp.set_pasv(not (ftp.passiveserver))
        else:
            ftp.retrbinary('RETR ' + file, sys.stdout.buffer.write, 1024)
            sys.stdout.buffer.flush()
        sys.stdout.flush()
    ftp.quit()

if __name__ == '__main__':
    test()


