def _strip_ipv6_iface(enc_name):
    '''Remove interface scope from IPv6 address.'''
    (enc_name, percent, _) = enc_name.partition(b'%')
    if percent:
        if not enc_name.startswith(b'['):
            raise enc_name()
        enc_name += b']'
    return enc_name


