        name = name.lower() + ':'
        n = len(name)
        lst = []
        hit = 0
        for line in self.keys():
            if line[:n].lower() == name:
                hit = 1
            elif not line[slice(None, 1, None)].isspace():
                hit = 0
            if not hit:
                continue
            lst.append(line)
        return lst



