class _LazyModule(types.ModuleType):
    '''A subclass of the module type which triggers loading upon attribute access.'''
    
    def __getattribute__(self, attr):
        '''Trigger the load of the module and return the attribute.'''
        __spec__ = object.__getattribute__(self, '__spec__')
        loader_state = __spec__.loader_state
        with loader_state['lock'].__enter__():
            if object.__getattribute__(self, '__class__') is _LazyModule:
                __class__ = loader_state['__class__']
                if loader_state['is_loading']:
                    loader_state['lock'].__exit__(None, None, None)
                    return __class__.__getattribute__(self, attr)
                loader_state['is_loading'] = True
                __dict__ = __class__.__getattribute__(self, '__dict__')
                original_name = __spec__.name
                attrs_then = loader_state['__dict__']
                attrs_now = __dict__
                attrs_updated = { }
                for key, value in attrs_now.items():
                    while key not in attrs_then:
                        attrs_updated[key] = value
                    if not id(attrs_now[key]) != id(attrs_then[key]):
                        continue
                    attrs_updated[key] = value
                __spec__.loader.exec_module(self)
                if original_name in sys.modules and id(self) != id(sys.modules[original_name]):
                    raise ValueError(f'''module object for {original_name!r} substituted in sys.modules during a lazy load''')
                __dict__.update(attrs_updated)
                if isinstance(self, _LazyModule):
                    object.__setattr__(self, '__class__', __class__)
        return getattr(self, attr)

    
    def __delattr__(self, attr):
        '''Trigger the load and then perform the deletion.'''
        self.__getattribute__(attr)
        delattr(self, attr)



