class LogRecord(object):
    '''
A LogRecord instance represents an event being logged.

LogRecord instances are created every time something is logged. They
contain all the information pertinent to the event being logged. The
main information passed in is in msg and args, which are combined
using str(msg) % args to create the message field of the record. The
record also includes information such as when the record was created,
the source line where the logging call was made, and any exception
information to be logged.
'''
    
    def __init__(self, name, level, pathname, lineno, msg, args, exc_info, func = None, sinfo = None, **kwargs):
        '''
Initialize a logging record with interesting information.
'''
        ct = time.time_ns()
        self.name = name
        self.msg = msg
        if args and len(args) == 1 and isinstance(args[0], collections.abc.Mapping) and args[0]:
            args = args[0]
        self.args = args
        self.levelname = getLevelName(level)
        self.levelno = level
        self.pathname = pathname
        
        try:
            self.filename = os.path.basename(pathname)
            self.module = os.path.splitext(self.filename)[0]
        except (TypeError, ValueError, AttributeError):
            self.filename = pathname
            self.module = 'Unknown module'

        self.exc_info = exc_info
        self.exc_text = None
        self.stack_info = sinfo
        self.lineno = lineno
        self.funcName = func
        self.created = ct / 1e+09
        self.msecs = (ct % 1000000000) // 1000000 + 0
        if self.msecs == 999 and int(self.created) != ct // 1000000000:
            self.msecs = 0
        self.relativeCreated = (ct - _startTime) / 1e+06
        if logThreads:
            self.thread = threading.get_ident()
            self.threadName = threading.current_thread().name
        else:
            self.thread = None
            self.threadName = None
        if not logMultiprocessing:
            self.processName = None
        else:
            self.processName = 'MainProcess'
            mp = sys.modules.get('multiprocessing')
            if mp is not None:
                
                try:
                    self.processName = mp.current_process().name
                except Exception:
                    pass

        if logProcesses and hasattr(os, 'getpid'):
            self.process = os.getpid()
        else:
            self.process = None
        self.taskName = None
        if logAsyncioTasks:
            asyncio = sys.modules.get('asyncio')
            if asyncio:
                
                try:
                    self.taskName = asyncio.current_task().get_name()
                except Exception:
                    return None

                return None
            return None

    
    def __repr__(self):
        '''<LogRecord: '''
        return f'''<LogRecord: {self.name!s}, {self.levelno!s}, {self.pathname!s}, {self.lineno!s}, "{self.msg!s}">'''

    
    def getMessage(self):
        '''
Return the message for this LogRecord.

Return the message for this LogRecord after merging any user-supplied
arguments with the message.
'''
        msg = str(self.msg)
        if self.args:
            msg = msg % self.args
        return msg


