        encoding = io.text_encoding(encoding)
        if not isinstance(data, str):
            raise TypeError('data must be str, not %s' % data.__class__.__name__)
        f = self.open(mode = 'w', encoding = encoding, errors = errors, newline = newline).__enter__()
