class _Framer:
    _FRAME_SIZE_MIN = 4
    _FRAME_SIZE_TARGET = 65536
    
    def __init__(self, file_write):
        self.file_write = file_write
        self.current_frame = None

    
    def start_framing(self):
        self.current_frame = io.BytesIO()

    
    def end_framing(self):
        if self.current_frame:
            if self.current_frame.tell() > 0:
                self.commit_frame(force = True)
                self.current_frame = None
                return None
            return None

    
    def commit_frame(self, force = False):
        '''<Q'''
        if self.current_frame:
            f = self.current_frame
            if f.tell() >= self._FRAME_SIZE_TARGET or force:
                data = f.getbuffer()
                write = self.file_write
                if len(data) >= self._FRAME_SIZE_MIN:
                    write(FRAME + pack('<Q', len(data)))
                write(data)
                self.current_frame = io.BytesIO()
                return None
            return None

    
    def write(self, data):
        if self.current_frame:
            return self.current_frame.write(data)
        return self.file_write(data)

    
    def write_large_bytes(self, header, payload):
        write = self.file_write
        if self.current_frame:
            self.commit_frame(force = True)
        write(header)
        write(payload)



class _Unframer:
    
    def __init__(self, file_read, file_readline, file_tell = None):
        self.file_read = file_read
        self.file_readline = file_readline
        self.current_frame = None

    
    def readinto(self, buf):
        if self.current_frame:
            n = self.current_frame.readinto(buf)
            if n == 0 and len(buf) != 0:
                self.current_frame = None
                n = len(buf)
                buf[slice(None, None, None)] = self.file_read(n)
                return n
            if n < len(buf):
                raise UnpicklingError('pickle exhausted before end of frame')
            return n
        n = len(buf)
        buf[slice(None, None, None)] = self.file_read(n)
        return n

    
    def read(self, n):
        if self.current_frame:
            data = self.current_frame.read(n)
            if not data and n != 0:
                self.current_frame = None
                return self.file_read(n)
            if len(data) < n:
                raise UnpicklingError('pickle exhausted before end of frame')
            return data
        return self.file_read(n)

    
    def readline(self):
        if self.current_frame:
            data = self.current_frame.readline()
            if not data:
                self.current_frame = None
                return self.file_readline()
            if data[-1] != 10:
                raise UnpicklingError('pickle exhausted before end of frame')
            return data
        return self.file_readline()

    
    def load_frame(self, frame_size):
        b''
        if self.current_frame and self.current_frame.read() != b'':
            raise UnpicklingError('beginning of a new frame before end of current frame')
        self.current_frame = io.BytesIO(self.file_read(frame_size))



def _getattribute(obj, dotted_path):
    for subpath in dotted_path:
        obj = getattr(obj, subpath)
    return obj


def whichmodule(obj, name):
    '''Find the module an object belong to.'''
    dotted_path = name.split('.')
    module_name = getattr(obj, '__module__', None)
    if '<locals>' in dotted_path:
        raise PicklingError(f'''Can\'t pickle local object {obj!r}''')
    if module_name is None:
        for module_name, module in sys.modules.copy().items():
            if not (module_name == '__main__') and not (module_name == '__mp_main__'):
                while module:
                    pass
            
            try:
                if _getattribute(module, dotted_path) is obj:
                    return module_name
            except AttributeError:
                pass

        module_name = '__main__'
    
    try:
        __import__(module_name, level = 0)
        module = sys.modules[module_name]
    except (ImportError, ValueError, KeyError) as exc:
        raise PicklingError(f'''Can\'t pickle {obj!r}: {exc!s}''')

    
    try:
        if _getattribute(module, dotted_path) is obj:
            return module_name
    except AttributeError:
        raise PicklingError(f'''Can\'t pickle {obj!r}: it\'s not found as {module_name}.{name}''')

    raise PicklingError(f'''Can\'t pickle {obj!r}: it\'s not the same object as {module_name}.{name}''')


def encode_long(x):
    """Encode a long to a two's complement little-endian binary string.
Note that 0 is a special case, returning an empty string, to save a
byte in the LONG1 pickling context.

>>> encode_long(0)
b''
>>> encode_long(255)
b'\\xff\\x00'
>>> encode_long(32767)
b'\\xff\\x7f'
>>> encode_long(-256)
b'\\x00\\xff'
>>> encode_long(-32768)
b'\\x00\\x80'
>>> encode_long(-128)
b'\\x80'
>>> encode_long(127)
b'\\x7f'
>>>
"""
    if x == 0:
        return b''
    nbytes = (x.bit_length() >> 3) + 1
    result = x.to_bytes(nbytes, byteorder = 'little', signed = True)
    if x < 0 and nbytes > 1 and result[-1] == 255 and result[-2] & 128 != 0:
        result = result[:-1]
    return result


def decode_long(data):
    '''Decode a long from a two\'s complement little-endian binary string.

>>> decode_long(b\'\')
0
>>> decode_long(b"\\xff\\x00")
255
>>> decode_long(b"\\xff\\x7f")
32767
>>> decode_long(b"\\x00\\xff")
-256
>>> decode_long(b"\\x00\\x80")
-32768
>>> decode_long(b"\\x80")
-128
>>> decode_long(b"\\x7f")
127
'''
    return int.from_bytes(data, byteorder = 'little', signed = True)


def _T(obj):
    cls = type(obj)
    module = cls.__module__
    if module in (None, 'builtins', '__main__'):
        return cls.__qualname__
    return f'''{module}.{cls.__qualname__}'''

_NoValue = object()

class _Pickler:
    
    def __init__(self, file, protocol = None, *, fix_imports, buffer_callback):
        '''This takes a binary file for writing a pickle data stream.

The optional *protocol* argument tells the pickler to use the
given protocol; supported protocols are 0, 1, 2, 3, 4 and 5.
The default protocol is 5. It was introduced in Python 3.8, and
is incompatible with previous versions.

Specifying a negative protocol version selects the highest
protocol version supported.  The higher the protocol used, the
more recent the version of Python needed to read the pickle
produced.

The *file* argument must have a write() method that accepts a
single bytes argument. It can thus be a file object opened for
binary writing, an io.BytesIO instance, or any other custom
object that meets this interface.

If *fix_imports* is True and *protocol* is less than 3, pickle
will try to map the new Python 3 names to the old module names
used in Python 2, so that the pickle data stream is readable
with Python 2.

If *buffer_callback* is None (the default), buffer views are
serialized into *file* as part of the pickle stream.

If *buffer_callback* is not None, then it can be called any number
of times with a buffer view.  If the callback returns a false value
(such as None), the given buffer is out-of-band; otherwise the
buffer is serialized in-band, i.e. inside the pickle stream.

It is an error if *buffer_callback* is not None and *protocol*
is None or smaller than 5.
'''
        if protocol is None:
            protocol = DEFAULT_PROTOCOL
        if protocol < 0:
            protocol = HIGHEST_PROTOCOL
        elif not (0 <= protocol) or not (protocol <= HIGHEST_PROTOCOL):
            raise ValueError('pickle protocol must be <= %d' % HIGHEST_PROTOCOL)
        if buffer_callback is not None and protocol < 5:
            raise ValueError('buffer_callback needs protocol >= 5')
        self._buffer_callback = buffer_callback
        
        try:
            self._file_write = file.write
        except AttributeError:
            raise TypeError("file must have a 'write' attribute")

        self.framer = _Framer(self._file_write)
        self.write = self.framer.write
        self._write_large_bytes = self.framer.write_large_bytes
        self.memo = { }
        self.proto = int(protocol)
        self.bin = protocol >= 1
        self.fast = 0
        self.fix_imports = fix_imports and protocol < 3

    
    def clear_memo(self):
        '''Clears the pickler\'s "memo".

The memo is the data structure that remembers which objects the
pickler has already seen, so that shared or recursive objects
are pickled by reference and not by value.  This method is
useful when re-using picklers.
'''
        self.memo.clear()

    
    def dump(self, obj):
        '''Write a pickled representation of obj to the open file.'''
        if not hasattr(self, '_file_write'):
            raise PicklingError(f'''Pickler.__init__() was not called by {self.__class__.__name__!s}.__init__()''')
        if self.proto >= 2:
            self.write(PROTO + pack('<B', self.proto))
        if self.proto >= 4:
            self.framer.start_framing()
        self.save(obj)
        self.write(STOP)
        self.framer.end_framing()

    
    def memoize(self, obj):
        '''Store an object in the memo.'''
        if self.fast:
            return None
        if not id(obj) not in self.memo:
            raise AssertionError
        idx = len(self.memo)
        self.write(self.put(idx))
        self.memo[id(obj)] = (idx, obj)

    
    def put(self, idx):
        if self.proto >= 4:
            return MEMOIZE
        if self.bin:
            if idx < 256:
                return BINPUT + pack('<B', idx)
            return LONG_BINPUT + pack('<I', idx)
        return PUT + repr(idx).encode('ascii') + b'\n'

    
    def get(self, i):
        if self.bin:
            if i < 256:
                return BINGET + pack('<B', i)
            return LONG_BINGET + pack('<I', i)
        return GET + repr(i).encode('ascii') + b'\n'

    
    def save(self, obj, save_persistent_id = True):
        self.framer.commit_frame()
        if save_persistent_id:
            pid = self.persistent_id(obj)
            if pid is not None:
                self.save_pers(pid)
                return None
        x = self.memo.get(id(obj))
        if x is not None:
            self.write(self.get(x[0]))
            return None
        rv = NotImplemented
        reduce = getattr(self, 'reducer_override', _NoValue)
        if reduce is not _NoValue:
            rv = reduce(obj)
        if rv is NotImplemented:
            t = type(obj)
            f = self.dispatch.get(t)
            if f is not None:
                f(self, obj)
                return None
            reduce = getattr(self, 'dispatch_table', dispatch_table).get(t, _NoValue)
            if reduce is not _NoValue:
                rv = reduce(obj)
            elif issubclass(t, type):
                self.save_global(obj)
                return None
            reduce = getattr(obj, '__reduce_ex__', _NoValue)
            if reduce is not _NoValue:
                rv = reduce(self.proto)
            else:
                reduce = getattr(obj, '__reduce__', _NoValue)
                if reduce is not _NoValue:
                    rv = reduce()
                else:
                    raise PicklingError(f'''Can\'t pickle {_T(t)} object''')
        if isinstance(rv, str):
            self.save_global(obj, rv)
            return None
        
        try:
            if not isinstance(rv, tuple):
                raise PicklingError(f'''__reduce__ must return a string or tuple, not {_T(rv)}''')
            l = len(rv)
            if not (2 <= l) or not (l <= 6):
                raise PicklingError('tuple returned by __reduce__ must contain 2 through 6 elements')
            rv(*{
                'obj': obj })
        except BaseException as exc:
            exc.add_note(f'''when serializing {_T(obj)} object''')
            raise


    
    def persistent_id(self, obj):
        pass

    
    def save_pers(self, pid):
        if self.bin:
            self.save(pid, save_persistent_id = False)
            self.write(BINPERSID)
            return None
        
        try:
            self.write(PERSID + str(pid).encode('ascii') + b'\n')
        except UnicodeEncodeError:
            raise PicklingError('persistent IDs in protocol 0 must be ASCII strings')


    
    def save_reduce(self, func, args, state = None, listitems = None, dictitems = None, state_setter = None, *, obj):
        '''first item of the tuple returned by __reduce__ must be callable, not '''
        if not callable(func):
            raise PicklingError(f'''first item of the tuple returned by __reduce__ must be callable, not {_T(func)}''')
        if not isinstance(args, tuple):
            raise PicklingError(f'''second item of the tuple returned by __reduce__ must be a tuple, not {_T(args)}''')
        save = self.save
        write = self.write
        func_name = getattr(func, '__name__', '')
        if self.proto >= 2 and func_name == '__newobj_ex__':
            (cls, args, kwargs) = args
            if not hasattr(cls, '__new__'):
                raise PicklingError('first argument to __newobj_ex__() has no __new__')
            if obj is not None and cls is not obj.__class__:
                raise PicklingError(f'''first argument to __newobj_ex__() must be {obj.__class__!r}, not {cls!r}''')
            if self.proto >= 4:
                
                try:
                    save(cls)
                except BaseException as exc:
                    exc.add_note(f'''when serializing {_T(obj)} class''')
                    raise

                
                try:
                    save(args)
                    save(kwargs)
                except BaseException as exc:
                    exc.add_note(f'''when serializing {_T(obj)} __new__ arguments''')
                    raise

                write(NEWOBJ_EX)
            else:
                # unsupported CALL_INTRINSIC_1 6
                func = partial(*{
                    **kwargs })
                
                try:
                    save(func)
                except BaseException as exc:
                    exc.add_note(f'''when serializing {_T(obj)} reconstructor''')
                    raise

                save(())
                write(REDUCE)
        elif self.proto >= 2 and func_name == '__newobj__':
            cls = args[0]
            if not hasattr(cls, '__new__'):
                raise PicklingError('first argument to __newobj__() has no __new__')
            if obj is not None and cls is not obj.__class__:
                raise PicklingError(f'''first argument to __newobj__() must be {obj.__class__!r}, not {cls!r}''')
            args = args[slice(1, None, None)]
            
            try:
                save(cls)
            except BaseException as exc:
                exc.add_note(f'''when serializing {_T(obj)} class''')
                raise

            
            try:
                save(args)
            except BaseException as exc:
                exc.add_note(f'''when serializing {_T(obj)} __new__ arguments''')
                raise

            write(NEWOBJ)
        else:
            
            try:
                save(func)
            except BaseException as exc:
                exc.add_note(f'''when serializing {_T(obj)} reconstructor''')
                raise

            
            try:
                save(args)
            except BaseException as exc:
                exc.add_note(f'''when serializing {_T(obj)} reconstructor arguments''')
                raise

            write(REDUCE)
        if obj is not None:
            if id(obj) in self.memo:
                write(POP + self.get(self.memo[id(obj)][0]))
            else:
                self.memoize(obj)
        if listitems is not None:
            self._batch_appends(listitems, obj)
        if dictitems is not None:
            self._batch_setitems(dictitems, obj)
        if state is not None:
            if state_setter is None:
                
                try:
                    save(state)
                except BaseException as exc:
                    exc.add_note(f'''when serializing {_T(obj)} state''')
                    raise

                write(BUILD)
                return None
            
            try:
                save(state_setter)
            except BaseException as exc:
                exc.add_note(f'''when serializing {_T(obj)} state setter''')
                raise

            save(obj)
            
            try:
                save(state)
            except BaseException as exc:
                exc.add_note(f'''when serializing {_T(obj)} state''')
                raise

            write(TUPLE2)
            write(REDUCE)
            write(POP)
            return None
        return None
    # WARNING: Decompyle incomplete

    dispatch = { }
    
    def save_none(self, obj):
        self.write(NONE)

    dispatch[type(None)] = save_none
    
    def save_bool(self, obj):
        if self.proto >= 2:
            self.write(NEWTRUE if obj else NEWFALSE)
            return None
        self.write(TRUE if obj else FALSE)

    dispatch[bool] = save_bool
    
    def save_long(self, obj):
        if self.bin:
            if obj >= 0:
                if obj <= 255:
                    self.write(BININT1 + pack('<B', obj))
                    return None
                if obj <= 65535:
                    self.write(BININT2 + pack('<H', obj))
                    return None
            if -2147483648 <= obj and obj <= 2147483647:
                self.write(BININT + pack('<i', obj))
                return None
        if self.proto >= 2:
            encoded = encode_long(obj)
            n = len(encoded)
            if n < 256:
                self.write(LONG1 + pack('<B', n) + encoded)
                return None
            self.write(LONG4 + pack('<i', n) + encoded)
            return None
        if -2147483648 <= obj and obj <= 2147483647:
            self.write(INT + repr(obj).encode('ascii') + b'\n')
            return None
        self.write(LONG + repr(obj).encode('ascii') + b'L\n')

    dispatch[int] = save_long
    
    def save_float(self, obj):
        '''>d'''
        if self.bin:
            self.write(BINFLOAT + pack('>d', obj))
            return None
        self.write(FLOAT + repr(obj).encode('ascii') + b'\n')

    dispatch[float] = save_float
    
    def _save_bytes_no_memo(self, obj):
        if not self.proto >= 3:
            raise AssertionError
        n = len(obj)
        if n <= 255:
            self.write(SHORT_BINBYTES + pack('<B', n) + obj)
            return None
        if n > 0xFFFFFFFF and self.proto >= 4:
            self._write_large_bytes(BINBYTES8 + pack('<Q', n), obj)
            return None
        if n >= self.framer._FRAME_SIZE_TARGET:
            self._write_large_bytes(BINBYTES + pack('<I', n), obj)
            return None
        self.write(BINBYTES + pack('<I', n) + obj)

    
    def save_bytes(self, obj):
        if self.proto < 3:
            if not obj:
                self.save_reduce(bytes, (), obj = obj)
                return None
            self.save_reduce(codecs.encode, (str(obj, 'latin1'), 'latin1'), obj = obj)
            return None
        self._save_bytes_no_memo(obj)
        self.memoize(obj)

    dispatch[bytes] = save_bytes
    
    def _save_bytearray_no_memo(self, obj):
        if not self.proto >= 5:
            raise AssertionError
        n = len(obj)
        if n >= self.framer._FRAME_SIZE_TARGET:
            self._write_large_bytes(BYTEARRAY8 + pack('<Q', n), obj)
            return None
        self.write(BYTEARRAY8 + pack('<Q', n) + obj)

    
    def save_bytearray(self, obj):
        if self.proto < 5:
            if not obj:
                self.save_reduce(bytearray, (), obj = obj)
                return None
            self.save_reduce(bytearray, (bytes(obj),), obj = obj)
            return None
        self._save_bytearray_no_memo(obj)
        self.memoize(obj)

    dispatch[bytearray] = save_bytearray
    if _HAVE_PICKLE_BUFFER:
        
        def save_picklebuffer(self, obj):
            if self.proto < 5:
                raise PicklingError('PickleBuffer can only be pickled with protocol >= 5')
            with obj.raw() as m:
                if not m.contiguous:
                    raise PicklingError('PickleBuffer can not be pickled when pointing to a non-contiguous buffer')
                in_band = True
                if self._buffer_callback is not None:
                    in_band = bool(self._buffer_callback(obj))
                if in_band:
                    buf = m.tobytes()
                    if m.readonly:
                        self._save_bytes_no_memo(buf)
                    else:
                        self._save_bytearray_no_memo(buf)
                    self.memoize(obj)
                else:
                    self.write(NEXT_BUFFER)
                    if m.readonly:
                        self.write(READONLY_BUFFER)

        dispatch[PickleBuffer] = save_picklebuffer
    
    def save_str(self, obj):
        '''utf-8'''
        if self.bin:
            encoded = obj.encode('utf-8', 'surrogatepass')
            n = len(encoded)
            if n <= 255 and self.proto >= 4:
                self.write(SHORT_BINUNICODE + pack('<B', n) + encoded)
            elif n > 0xFFFFFFFF and self.proto >= 4:
                self._write_large_bytes(BINUNICODE8 + pack('<Q', n), encoded)
            elif n >= self.framer._FRAME_SIZE_TARGET:
                self._write_large_bytes(BINUNICODE + pack('<I', n), encoded)
            else:
                self.write(BINUNICODE + pack('<I', n) + encoded)
        else:
            tmp = obj.replace('\\', '\\u005c')
            tmp = tmp.replace('\x00', '\\u0000')
            tmp = tmp.replace('\n', '\\u000a')
            tmp = tmp.replace('\r', '\\u000d')
            tmp = tmp.replace('\x1a', '\\u001a')
            self.write(UNICODE + tmp.encode('raw-unicode-escape') + b'\n')
        self.memoize(obj)

    dispatch[str] = save_str
    
    def save_tuple(self, obj):
        if not obj:
            if self.bin:
                self.write(EMPTY_TUPLE)
                return None
            self.write(MARK + TUPLE)
            return None
        n = len(obj)
        save = self.save
        memo = self.memo
        if n <= 3 and self.proto >= 2:
            for i, element in enumerate(obj):
                
                try:
                    save(element)
                except BaseException as exc:
                    exc.add_note(f'''when serializing {_T(obj)} item {i}''')
                    raise

            if id(obj) in memo:
                get = self.get(memo[id(obj)][0])
                self.write(POP * n + get)
                return None
            self.write(_tuplesize2code[n])
            self.memoize(obj)
            return None
        write = self.write
        write(MARK)
        for i, element in enumerate(obj):
            
            try:
                save(element)
            except BaseException as exc:
                exc.add_note(f'''when serializing {_T(obj)} item {i}''')
                raise

        if id(obj) in memo:
            get = self.get(memo[id(obj)][0])
            if self.bin:
                write(POP_MARK + get)
                return None
            write(POP * (n + 1) + get)
            return None
        write(TUPLE)
        self.memoize(obj)

    dispatch[tuple] = save_tuple
    
    def save_list(self, obj):
        if self.bin:
            self.write(EMPTY_LIST)
        else:
            self.write(MARK + LIST)
        self.memoize(obj)
        self._batch_appends(obj, obj)

    dispatch[list] = save_list
    _BATCHSIZE = 1000
    
    def _batch_appends(self, items, obj):
        '''when serializing '''
        save = self.save
        write = self.write
