        if obj is type(None):
            return self.save_reduce(type, (None,), obj = obj)
        if obj is type(NotImplemented):
            return self.save_reduce(type, (NotImplemented,), obj = obj)
        if obj is type(...):
            return self.save_reduce(type, (...,), obj = obj)
        return self.save_global(obj)

