def _test(N = 10000):
    _test_generator(N, random, ())
    _test_generator(N, normalvariate, (0, 1))
    _test_generator(N, lognormvariate, (0, 1))
    _test_generator(N, vonmisesvariate, (0, 1))
    _test_generator(N, binomialvariate, (15, 0.6))
    _test_generator(N, binomialvariate, (100, 0.75))
    _test_generator(N, gammavariate, (0.01, 1))
    _test_generator(N, gammavariate, (0.1, 1))
    _test_generator(N, gammavariate, (0.1, 2))
    _test_generator(N, gammavariate, (0.5, 1))
    _test_generator(N, gammavariate, (0.9, 1))
    _test_generator(N, gammavariate, (1, 1))
    _test_generator(N, gammavariate, (2, 1))
    _test_generator(N, gammavariate, (20, 1))
    _test_generator(N, gammavariate, (200, 1))
    _test_generator(N, gauss, (0, 1))
    _test_generator(N, betavariate, (3, 3))
    _test_generator(N, triangular, (0, 1, 0.333333))

if hasattr(_os, 'fork'):
    _os.register_at_fork(after_in_child = _inst.seed)

def _parse_args(arg_list):
    import argparse
    parser = argparse.ArgumentParser(formatter_class = argparse.RawTextHelpFormatter, color = True)
    group = parser.add_mutually_exclusive_group()
    group.add_argument('-c', '--choice', nargs = '+', help = 'print a random choice')
    group.add_argument('-i', '--integer', type = int, metavar = 'N', help = 'print a random integer between 1 and N inclusive')
    group.add_argument('-f', '--float', type = float, metavar = 'N', help = 'print a random floating-point number between 0 and N inclusive')
    group.add_argument('--test', type = int, const = 10000, nargs = '?', help = argparse.SUPPRESS)
    parser.add_argument('input', nargs = '*', help = 'if no options given, output depends on the input\n    string or multiple: same as --choice\n    integer: same as --integer\n    float: same as --float')
    args = parser.parse_args(arg_list)
    return (args, parser.format_help())


def main(arg_list = None):
    args, help_text = _parse_args(arg_list)
    if args.choice:
        return choice(args.choice)
    if args.integer is not None:
        return randint(1, args.integer)
    if args.float is not None:
        return uniform(0, args.float)
    if args.test:
        _test(args.test)
        return ''
    if len(args.input) == 1:
        val = args.input[0]
        
        try:
            val = int(val)
            return randint(1, val)
        except ValueError:
            
            try:
                val = float(val)
            except ValueError:
                return choice(val.split())

            return uniform(0, val)

    if len(args.input) >= 2:
        return choice(args.input)
    return help_text
# WARNING: Decompyle incomplete

if __name__ == '__main__':
    print(main())


