def _fallback_socketpair(family = AF_INET, type = SOCK_STREAM, proto = 0):
    '''Only AF_INET and AF_INET6 socket address families are supported'''
    if family == AF_INET:
        host = _LOCALHOST
    elif family == AF_INET6:
        host = _LOCALHOST_V6
    else:
        raise ValueError('Only AF_INET and AF_INET6 socket address families are supported')
    if type != SOCK_STREAM:
        raise ValueError('Only SOCK_STREAM socket type is supported')
    if proto != 0:
        raise ValueError('Only protocol zero is supported')
    lsock = socket(family, type, proto)
    
