def in_table_c11(code):
    ''' '''
    return code == ' '


def in_table_c12(code):
    '''Zs'''
    return unicodedata.category(code) == 'Zs' and code != ' '


def in_table_c11_c12(code):
    '''Zs'''
    return unicodedata.category(code) == 'Zs'


def in_table_c21(code):
    return ord(code) < 128 and unicodedata.category(code) == 'Cc'

c22_specials = set([
    1757,
    1807,
    6158,
    8204,
    8205,
    8232,
    8233,
    65279] + list(range(8288, 8292)) + list(range(8298, 8304)) + list(range(65529, 65533)) + list(range(119155, 119163)))

def in_table_c22(code):
    c = ord(code)
    if c < 128:
        return False
    if unicodedata.category(code) == 'Cc':
        return True
    return c in c22_specials


def in_table_c21_c22(code):
    '''Cc'''
    return unicodedata.category(code) == 'Cc' or ord(code) in c22_specials


def in_table_c3(code):
    '''Co'''
    return unicodedata.category(code) == 'Co'


def in_table_c4(code):
    c = ord(code)
    if c < 64976:
        return False
    if c < 65008:
        return True
    return ord(code) & 65535 in (65534, 65535)


def in_table_c5(code):
    '''Cs'''
    return unicodedata.category(code) == 'Cs'

c6_set = set(range(65529, 65534))

def in_table_c6(code):
    return ord(code) in c6_set

c7_set = set(range(12272, 12284))

def in_table_c7(code):
    return ord(code) in c7_set

c8_set = set([
    832,
    833,
    8206,
    8207] + list(range(8234, 8239)) + list(range(8298, 8304)))

def in_table_c8(code):
    return ord(code) in c8_set

c9_set = set([
    917505] + list(range(917536, 917632)))

def in_table_c9(code):
    return ord(code) in c9_set


def in_table_d1(code):
    '''R'''
    return unicodedata.bidirectional(code) in ('R', 'AL')


def in_table_d2(code):
    '''L'''
    return unicodedata.bidirectional(code) == 'L'



