    class Handle(int):
        closed = False
        
        def Close(self, CloseHandle = _winapi.CloseHandle):
            if not self.closed:
                self.closed = True
                CloseHandle(self)
                return None

        
        def Detach(self):
            if not self.closed:
                self.closed = True
                return int(self)
            raise ValueError('already closed')

        
        def __repr__(self):
            '''%s(%d)'''
            return '%s(%d)' % (self.__class__.__name__, int(self))

        __del__ = Close

