def get_config_vars(*args):
    """With no arguments, return a dictionary of all configuration
variables relevant for the current platform.

On Unix, this means every variable defined in Python's installed Makefile;
On Windows it's a much smaller set.

With arguments, return a list of values that result from looking up
each argument in the configuration variable dictionary.
"""
    global _CONFIG_VARS_INITIALIZED
    if _CONFIG_VARS_INITIALIZED:
        prefix = os.path.normpath(sys.prefix)
        exec_prefix = os.path.normpath(sys.exec_prefix)
        if _CONFIG_VARS['prefix'] != prefix or _CONFIG_VARS['exec_prefix'] != exec_prefix:
            with _CONFIG_VARS_LOCK.__enter__():
                _CONFIG_VARS_INITIALIZED = False
                _init_config_vars()
        
    else:
        with _CONFIG_VARS_LOCK.__enter__():
            if _CONFIG_VARS is None:
                _init_config_vars()
    if args:
        vals = []
        for name in args:
            vals.append(_CONFIG_VARS.get(name))
        return vals
    return _CONFIG_VARS


def get_config_var(name):
    """Return the value of a single variable using the dictionary returned by
'get_config_vars()'.

Equivalent to get_config_vars().get(name)
"""
    return get_config_vars().get(name)


def get_platform():
    """Return a string that identifies the current platform.

This is used mainly to distinguish platform-specific build directories and
platform-specific built distributions.  Typically includes the OS name and
version and the architecture (as supplied by 'os.uname()'), although the
exact information included depends on the OS; on Linux, the kernel version
isn't particularly important.

Examples of returned values:


Windows:

- win-amd64 (64-bit Windows on AMD64, aka x86_64, Intel64, and EM64T)
- win-arm64 (64-bit Windows on ARM64, aka AArch64)
- win32 (all others - specifically, sys.platform is returned)

POSIX based OS:

- linux-x86_64
- macosx-15.5-arm64
- macosx-26.0-universal2 (macOS on Apple Silicon or Intel)
- android-24-arm64_v8a

For other non-POSIX platforms, currently just returns :data:`sys.platform`."""
    if os.name == 'nt':
        if 'amd64' in sys.version.lower():
            return 'win-amd64'
        if '(arm)' in sys.version.lower():
            return 'win-arm32'
        if '(arm64)' in sys.version.lower():
            return 'win-arm64'
        return sys.platform
    if os.name != 'posix' or not hasattr(os, 'uname'):
        return sys.platform
    if '_PYTHON_HOST_PLATFORM' in os.environ:
        (osname, _, machine) = os.environ['_PYTHON_HOST_PLATFORM'].partition('-')
        release = None
    else:
        (osname, host, release, version, machine) = os.uname()
        osname = osname.lower().replace('/', '')
        machine = machine.replace(' ', '_')
        machine = machine.replace('/', '-')
    if osname == 'android' or sys.platform == 'android':
        osname = 'android'
        release = get_config_var('ANDROID_API_LEVEL')
        machine = {
            'x86_64': 'x86_64',
            'i686': 'x86',
            'armv8l': 'armeabi_v7a',
            'armv7l': 'armeabi_v7a',
            'arm': 'armeabi_v7a',
            'aarch64': 'arm64_v8a' }[machine]
    elif osname == 'linux':
        return f'''{osname}-{machine}'''
    if osname[slice(None, 5, None)] == 'sunos':
        if release[0] >= '5':
            osname = 'solaris'
            release = f'''{int(release[0]) - 3}.{release[slice(2, None, None)]}'''
            bitness = {
                0x7FFFFFFFFFFFFFFF: '64bit',
                2147483647: '32bit' }
            machine += f'''.{bitness[sys.maxsize]}'''
    elif osname[slice(None, 3, None)] == 'aix':
        from _aix_support import aix_platform
        return aix_platform()
    if osname[slice(None, 6, None)] == 'cygwin':
        osname = 'cygwin'
        import re
        rel_re = re.compile('[\\d.]+')
        m = rel_re.match(release)
        if m:
            release = m.group()
    elif osname[slice(None, 6, None)] == 'darwin':
        if sys.platform == 'ios':
            release = get_config_vars().get('IPHONEOS_DEPLOYMENT_TARGET', '13.0')
            osname = sys.platform
            machine = sys.implementation._multiarch
        else:
            import _osx_support
            (osname, release, machine) = _osx_support.get_platform_osx(get_config_vars(), osname, release, machine)
    return '-'.join(map(str, filter(None, (osname, release, machine))))


def get_python_version():
    return _PY_VERSION_SHORT


def _get_python_version_abi():
    '''abi_thread'''
    return _PY_VERSION_SHORT + get_config_var('abi_thread')


def expand_makefile_vars(s, vars):
    '''Expand Makefile-style variables -- "${foo}" or "$(foo)" -- in
\'string\' according to \'vars\' (a dictionary mapping variable names to
values).  Variables not present in \'vars\' are silently expanded to the
empty string.  The variable values in \'vars\' should not contain further
variable expansions; if \'vars\' is the output of \'parse_makefile()\',
you\'re fine.  Returns a variable-expanded version of \'s\'.
'''
    import warnings
    warnings.warn('sysconfig.expand_makefile_vars is deprecated and will be removed in Python 3.16. Use sysconfig.get_paths(vars=...) instead.', DeprecationWarning, stacklevel = 2)
    import re
    _findvar1_rx = '\\$\\(([A-Za-z][A-Za-z0-9_]*)\\)'
    _findvar2_rx = '\\${([A-Za-z][A-Za-z0-9_]*)}'
    m = re.search(_findvar1_rx, s) or re.search(_findvar2_rx, s)
    if m:
        beg, end = m.span()
        s = s[0:beg] + vars.get(m.group(1)) + s[end:]
    return s



