class Tk(Wm, Misc):
    '''Toplevel widget of Tk which represents mostly the main window
of an application. It has an associated Tcl interpreter.'''
    _w = '.'
    
    def __init__(self, screenName = None, baseName = None, className = 'Tk', useTk = True, sync = False, use = None):
        '''Return a new top level widget on screen SCREENNAME. A new Tcl interpreter will
be created. BASENAME will be used for the identification of the profile file (see
readprofile).
It is constructed from sys.argv[0] without extensions if None is given. CLASSNAME
is the name of the widget class.'''
        self.master = None
        self.children = { }
        self._tkloaded = False
        self.tk = None
        if baseName is None:
            import os
            baseName = os.path.basename(sys.argv[0])
            baseName, ext = os.path.splitext(baseName)
            if ext not in ('.py', '.pyc'):
                baseName = baseName + ext
        interactive = False
        self.tk = _tkinter.create(screenName, baseName, className, interactive, wantobjects, useTk, sync, use)
        if _debug:
            self.tk.settrace(_print_command)
        if useTk:
            self._loadtk()
        if not sys.flags.ignore_environment:
            self.readprofile(baseName, className)
            return None

    
    def loadtk(self):
        if not self._tkloaded:
            self.tk.loadtk()
            self._loadtk()
            return None

    
    def _loadtk(self):
        global _default_root
        self._tkloaded = True
        tk_version = self.tk.getvar('tk_version')
        if tk_version != _tkinter.TK_VERSION:
            raise RuntimeError(f'''tk.h version ({_tkinter.TK_VERSION!s}) doesn\'t match libtk.a version ({tk_version!s})''')
        tcl_version = str(self.tk.getvar('tcl_version'))
        if tcl_version != _tkinter.TCL_VERSION:
            raise RuntimeError(f'''tcl.h version ({_tkinter.TCL_VERSION!s}) doesn\'t match libtcl.a version ({tcl_version!s})''')
        if self._tclCommands is None:
            self._tclCommands = []
        self.tk.createcommand('tkerror', _tkerror)
        self.tk.createcommand('exit', _exit)
        self._tclCommands.append('tkerror')
        self._tclCommands.append('exit')
        if _support_default_root and _default_root is None:
            _default_root = self
        self.protocol('WM_DELETE_WINDOW', self.destroy)

    
    def destroy(self):
        '''Destroy this and all descendants widgets. This will
end the application of this Tcl interpreter.'''
        global _default_root
        for c in list(self.children.values()):
            c.destroy()
        self.tk.call('destroy', self._w)
        Misc.destroy(self)
        if _support_default_root:
            if _default_root is self:
                _default_root = None
                return None
            return None

    
    def readprofile(self, baseName, className):
        '''Internal function. It reads .BASENAME.tcl and .CLASSNAME.tcl into
the Tcl Interpreter and calls exec on the contents of .BASENAME.py and
.CLASSNAME.py if such a file exists in the home directory.'''
        import os
        if 'HOME' in os.environ:
            home = os.environ['HOME']
        else:
            home = os.curdir
        class_tcl = os.path.join(home, '.%s.tcl' % className)
        class_py = os.path.join(home, '.%s.py' % className)
        base_tcl = os.path.join(home, '.%s.tcl' % baseName)
        base_py = os.path.join(home, '.%s.py' % baseName)
        dir = {
            'self': self }
        exec('from tkinter import *', dir)
        if os.path.isfile(class_tcl):
            self.tk.call('source', class_tcl)
        if os.path.isfile(class_py):
            exec(open(class_py).read(), dir)
        if os.path.isfile(base_tcl):
            self.tk.call('source', base_tcl)
        if os.path.isfile(base_py):
            exec(open(base_py).read(), dir)
            return None

    
    def report_callback_exception(self, exc, val, tb):
        '''Report callback exception on sys.stderr.

Applications may want to override this internal function, and
should when sys.stderr is None.'''
        import traceback
        print('Exception in Tkinter callback', file = sys.stderr)
        sys.last_exc = val
        sys.last_type = exc
        sys.last_value = val
        sys.last_traceback = tb
        traceback.print_exception(exc, val, tb)

    
    def __getattr__(self, attr):
        '''Delegate attribute access to the interpreter object'''
        return getattr(self.tk, attr)



def _print_command(cmd, *, file):
    if not isinstance(cmd, tuple):
        raise AssertionError
    cmd = _join(cmd)
    print(cmd, file = file)


def Tcl(screenName = None, baseName = None, className = 'Tk', useTk = False):
    return Tk(screenName, baseName, className, useTk)


class Pack:
    '''Geometry manager Pack.

Base class to use the methods pack_* in every widget.'''
    
    def pack_configure(self, cnf = { }, **kw):
        """Pack a widget in the parent widget. Use as options:
after=widget - pack it after you have packed widget
anchor=NSEW (or subset) - position widget according to
                          given direction
before=widget - pack it before you will pack widget
expand=bool - expand widget if parent size grows
fill=NONE or X or Y or BOTH - fill widget if widget grows
in=container - use the container widget to contain this widget
in_=container - see 'in' option description
ipadx=amount - add internal padding in x direction
ipady=amount - add internal padding in y direction
padx=amount - add padding in x direction
pady=amount - add padding in y direction
side=TOP or BOTTOM or LEFT or RIGHT -  where to add this widget.
"""
        self.tk.call(('pack', 'configure', self._w) + self._options(cnf, kw))

    pack = pack_configure
    configure = pack_configure
    config = pack_configure
    
    def pack_forget(self):
        '''Unmap this widget and do not use it for the packing order.'''
        self.tk.call('pack', 'forget', self._w)

    forget = pack_forget
    
    def pack_info(self):
        '''Return information about the packing options
for this widget.'''
        d = _splitdict(self.tk, self.tk.call('pack', 'info', self._w))
        if 'in' in d:
            d['in'] = self.nametowidget(d['in'])
        return d

    info = pack_info
    propagate = Misc.pack_propagate
    pack_propagate = Misc.pack_propagate
    slaves = Misc.pack_slaves
    pack_slaves = Misc.pack_slaves


