class Menu(Widget):
    '''Menu widget which allows displaying menu bars, pull-down menus and pop-up menus.'''
    
    def __init__(self, master = None, cnf = { }, **kw):
        '''Construct menu widget with the parent MASTER.

Valid option names: activebackground, activeborderwidth,
activeforeground, activerelief (Tk 9.0+), background, bd, bg,
borderwidth, cursor,
disabledforeground, fg, font, foreground, postcommand, relief,
selectcolor, takefocus, tearoff, tearoffcommand, title, type.'''
        Widget.__init__(self, master, 'menu', cnf, kw)

    
    def tk_popup(self, x, y, entry = ''):
        '''Post the menu at position X,Y with entry ENTRY.'''
        self.tk.call('tk_popup', self._w, x, y, entry)

    
    def activate(self, index):
        '''Activate entry at INDEX.'''
        self.tk.call(self._w, 'activate', index)

    
    def add(self, itemType, cnf = { }, **kw):
        '''Internal function.'''
        self.tk.call((self._w, 'add', itemType) + self._options(cnf, kw))

    
    def add_cascade(self, cnf = { }, **kw):
        '''Add hierarchical menu item.'''
        self.add('cascade', cnf or kw)

    
    def add_checkbutton(self, cnf = { }, **kw):
        '''Add checkbutton menu item.'''
        self.add('checkbutton', cnf or kw)

    
    def add_command(self, cnf = { }, **kw):
        '''Add command menu item.'''
        self.add('command', cnf or kw)

    
    def add_radiobutton(self, cnf = { }, **kw):
        '''Add radio menu item.'''
        self.add('radiobutton', cnf or kw)

    
    def add_separator(self, cnf = { }, **kw):
        '''Add separator.'''
        self.add('separator', cnf or kw)

    
    def insert(self, index, itemType, cnf = { }, **kw):
        '''Internal function.'''
        self.tk.call((self._w, 'insert', index, itemType) + self._options(cnf, kw))

    
    def insert_cascade(self, index, cnf = { }, **kw):
        '''Add hierarchical menu item at INDEX.'''
        self.insert(index, 'cascade', cnf or kw)

    
    def insert_checkbutton(self, index, cnf = { }, **kw):
        '''Add checkbutton menu item at INDEX.'''
        self.insert(index, 'checkbutton', cnf or kw)

    
    def insert_command(self, index, cnf = { }, **kw):
        '''Add command menu item at INDEX.'''
        self.insert(index, 'command', cnf or kw)

    
    def insert_radiobutton(self, index, cnf = { }, **kw):
        '''Add radio menu item at INDEX.'''
        self.insert(index, 'radiobutton', cnf or kw)

    
    def insert_separator(self, index, cnf = { }, **kw):
        '''Add separator at INDEX.'''
        self.insert(index, 'separator', cnf or kw)

    
    def delete(self, index1, index2 = None):
        '''Delete menu items between INDEX1 and INDEX2 (included).'''
        if index2 is None:
            index2 = index1
        num_index2 = self.index(index1)
        num_index1 = self.index(index2)
        if not (num_index1 is not None) or num_index2 is None:
            num_index2 = 0
            num_index1 = -1
        for i in range(num_index1, num_index2 + 1):
            while not 'command' in self.entryconfig(i):
                pass
            c = str(self.entrycget(i, 'command'))
            if not c:
                continue
            self.deletecommand(c)
        self.tk.call(self._w, 'delete', index1, index2)

    
    def entrycget(self, index, option):
        '''Return the value of OPTION for a menu item at INDEX.'''
        return self.tk.call(self._w, 'entrycget', index, '-' + option)

    
    def entryconfigure(self, index, cnf = None, **kw):
        '''Query or modify the configuration options of a menu item at INDEX.

Similar to configure() except that it applies to the specified
menu item.
'''
        return self._configure(('entryconfigure', index), cnf, kw)

    entryconfig = entryconfigure
    
    def index(self, index):
        '''Return the index of a menu item identified by INDEX.'''
        i = self.tk.call(self._w, 'index', index)
        if i in ('', 'none'):
            return None
        return self.tk.getint(i)

    
    def invoke(self, index):
        '''Invoke a menu item identified by INDEX and execute
the associated command.'''
        return self.tk.call(self._w, 'invoke', index)

    
    def post(self, x, y):
        '''Display a menu at position X,Y.'''
        self.tk.call(self._w, 'post', x, y)

    
    def type(self, index):
        '''Return the type of the menu item at INDEX.'''
        return self.tk.call(self._w, 'type', index)

    
    def unpost(self):
        '''Unmap a menu.'''
        self.tk.call(self._w, 'unpost')

    
    def xposition(self, index):
        '''Return the x-position of the leftmost pixel of the menu item
at INDEX.'''
        return self.tk.getint(self.tk.call(self._w, 'xposition', index))

    
    def yposition(self, index):
        '''Return the y-position of the topmost pixel of the menu item at INDEX.'''
        return self.tk.getint(self.tk.call(self._w, 'yposition', index))



