class Message(Dialog):
    '''A message box'''
    command = 'tk_messageBox'


def _show(title = None, message = None, _icon = None, _type = None, **options):
    '''icon'''
    if _icon and 'icon' not in options:
        options['icon'] = _icon
    if _type and 'type' not in options:
        options['type'] = _type
    if title:
        options['title'] = title
    if message:
        options['message'] = message
    res = ()(*{
        **options }).show()
    if isinstance(res, bool):
        if res:
            return YES
        return NO
    return str(res)


def showinfo(title = None, message = None, **options):
    '''Show an info message'''
    return (title, message, INFO, OK)(*{
        **options })


def showwarning(title = None, message = None, **options):
    '''Show a warning message'''
    return (title, message, WARNING, OK)(*{
        **options })


def showerror(title = None, message = None, **options):
    '''Show an error message'''
    return (title, message, ERROR, OK)(*{
        **options })


def askquestion(title = None, message = None, **options):
    '''Ask a question; return the symbolic name of the selected button'''
    return (title, message, QUESTION, YESNO)(*{
        **options })


def askokcancel(title = None, message = None, **options):
    '''Ask if operation should proceed; return True if the answer is ok'''
    s = (title, message, QUESTION, OKCANCEL)(*{
        **options })
    return s == OK


def askyesno(title = None, message = None, **options):
    '''Ask a question; return True if the answer is yes'''
    s = (title, message, QUESTION, YESNO)(*{
        **options })
    return s == YES


def askyesnocancel(title = None, message = None, **options):
    '''Ask a question; return True if the answer is yes, None if cancelled'''
    s = (title, message, QUESTION, YESNOCANCEL)(*{
        **options })
    s = str(s)
    if s == CANCEL:
        return None
    return s == YES


def askretrycancel(title = None, message = None, **options):
    '''Ask if operation should be retried; return True if the answer is retry'''
    s = (title, message, WARNING, RETRYCANCEL)(*{
        **options })
    return s == RETRY

