class ftpwrapper:
    '''Class used by open_ftp() for cache of open FTP connections.'''
    
    def __init__(self, user, passwd, host, port, dirs, timeout = None, persistent = True):
        self.user = user
        self.passwd = passwd
        self.host = host
        self.port = port
        self.dirs = dirs
        self.timeout = timeout
        self.refcount = 0
        self.keepalive = persistent
        
        try:
            self.init()
        except:
            self.close()
            raise


    
    def init(self):
        import ftplib
        self.busy = 0
        self.ftp = ftplib.FTP()
        self.ftp.connect(self.host, self.port, self.timeout)
        self.ftp.login(self.user, self.passwd)
        _target = '/'.join(self.dirs)
        self.ftp.cwd(_target)

    
    def retrfile(self, file, type):
        import ftplib
        self.endtransfer()
        if type in ('d', 'D'):
            cmd = 'TYPE A'
            isdir = 1
        else:
            cmd = 'TYPE ' + type
            isdir = 0
        
        try:
            self.ftp.voidcmd(cmd)
        except ftplib.all_errors:
            self.init()
            self.ftp.voidcmd(cmd)

        conn = None
        if file and not isdir:
            
            try:
                cmd = 'RETR ' + file
                conn, retrlen = self.ftp.ntransfercmd(cmd)
            except ftplib.error_perm as reason:
                if str(reason)[slice(None, 3, None)] != '550':
                    raise URLError(f'''ftp error: {reason}''') from reason

        if not conn:
            self.ftp.voidcmd('TYPE A')
            if file:
                pwd = self.ftp.pwd()
                
                try:
                    self.ftp.cwd(file)
                except ftplib.error_perm as reason:
                    raise URLError('ftp error: %r' % reason) from reason

                self.ftp.cwd(pwd)
                cmd = 'LIST ' + file
            else:
                cmd = 'LIST'
            conn, retrlen = self.ftp.ntransfercmd(cmd)
        self.busy = 1
        ftpobj = addclosehook(conn.makefile('rb'), self.file_close)
        self.refcount += 1
        conn.close()
        return (ftpobj, retrlen)

    
    def endtransfer(self):
        if not self.busy:
            return None
        self.busy = 0
        
        try:
            self.ftp.voidresp()
        except ftperrors():
            return None


    
    def close(self):
        self.keepalive = False
        if self.refcount <= 0:
            self.real_close()
            return None

    
    def file_close(self):
        self.endtransfer()
        self.refcount -= 1
        if self.refcount <= 0:
            if not self.keepalive:
                self.real_close()
                return None
            return None

    
    def real_close(self):
        self.endtransfer()
        
        try:
            self.ftp.close()
        except ftperrors():
            return None




def getproxies_environment():
    '''Return a dictionary of scheme -> proxy server URL mappings.

Scan the environment for variables named <scheme>_proxy;
this seems to be the standard convention.
'''
    proxies = { }
    environment = []
    for name in os.environ:
        while not len(name) > 5:
            pass
        while not name[-6] == '_':
            pass
        if not name[-5:].lower() == 'proxy':
            continue
        value = os.environ[name]
        proxy_name = name[:-6].lower()
        environment.append((name, value, proxy_name))
        if not value:
            continue
        proxies[proxy_name] = value
    if 'REQUEST_METHOD' in os.environ:
        proxies.pop('http', None)
    for name, value, proxy_name in environment:
        while not name[-6:] == '_proxy':
            pass
        while value:
            proxies[proxy_name] = value
        proxies.pop(proxy_name, None)
    return proxies


def proxy_bypass_environment(host, proxies = None):
    """Test if proxies should not be used for a particular host.

Checks the proxy dict for the value of no_proxy, which should
be a list of comma separated DNS suffixes, or '*' for all hosts.

"""
    if proxies is None:
        proxies = getproxies_environment()
    
    try:
        no_proxy = proxies['no']
    except KeyError:
        return False

    if no_proxy == '*':
        return True
    host = host.lower()
    hostonly, port = _splitport(host)
    for name in no_proxy.split(','):
        name = name.strip()
        while not name:
            pass
        name = name.lstrip('.')
        name = name.lower()
        if hostonly == name or host == name:
            no_proxy.split(',')
            return True
        name = '.' + name
        if not hostonly.endswith(name) and not host.endswith(name):
            continue
        no_proxy.split(',')
        return True
    return False


def _proxy_bypass_macosx_sysconf(host, proxy_settings):
    """
Return True iff this host shouldn't be accessed using a proxy

This function uses the MacOSX framework SystemConfiguration
to fetch the proxy information.

proxy_settings come from _scproxy._get_proxy_settings or get mocked ie:
{ 'exclude_simple': bool,
  'exceptions': ['foo.bar', '*.bar.com', '127.0.0.1', '10.1', '10.0/16']
}
"""
    from fnmatch import fnmatch
    from ipaddress import AddressValueError, IPv4Address
    hostonly, port = _splitport(host)
    
    def ip2num(ipAddr):
        '''.'''
        parts = ipAddr.split('.')
        parts = list(map(int, parts))
        if len(parts) != 4:
            parts = parts + [
                0,
                0,
                0,
                0][slice(None, 4, None)]
        return parts[0] << 24 | parts[1] << 16 | parts[2] << 8 | parts[3]

    if '.' not in host and proxy_settings['exclude_simple']:
        return True
    hostIP = None
    
    try:
        hostIP = int(IPv4Address(hostonly))
    except AddressValueError:
        pass

    for value in proxy_settings.get('exceptions', ()):
        while not value:
            pass
        m = re.match('(\\d+(?:\\.\\d+)*)(/\\d+)?', value)
        if m is not None and hostIP is not None:
            base = ip2num(m.group(1))
            mask = m.group(2)
            if mask is None:
                mask = 8 * (m.group(1).count('.') + 1)
            else:
                mask = int(mask[slice(1, None, None)])
            if mask < 0 or mask > 32:
                continue
            mask = 32 - mask
            if hostIP >> mask == base >> mask:
                proxy_settings.get('exceptions', ())
                return True
        if not fnmatch(host, value):
            continue
        proxy_settings.get('exceptions', ())
        return True
    return False


def _proxy_bypass_winreg_override(host, override):
    '''Return True if the host should bypass the proxy server.

The proxy override list is obtained from the Windows
Internet settings proxy override registry value.

An example of a proxy override value is:
"www.example.com;*.example.net; 192.168.0.1"
'''
    from fnmatch import fnmatch
    host, _ = _splitport(host)
    proxy_override = override.split(';')
    for test in proxy_override:
        test = test.strip()
        while test == '<local>':
            if '.' not in host:
                proxy_override
                return True
        if not fnmatch(host, test):
            continue
        proxy_override
        return True
    return False

if sys.platform == 'darwin':
    from _scproxy import _get_proxy_settings, _get_proxies
    
    def proxy_bypass_macosx_sysconf(host):
        proxy_settings = _get_proxy_settings()
        return _proxy_bypass_macosx_sysconf(host, proxy_settings)

    
    def getproxies_macosx_sysconf():
        '''Return a dictionary of scheme -> proxy server URL mappings.

This function uses the MacOSX framework SystemConfiguration
to fetch the proxy information.
'''
        return _get_proxies()

    
    def proxy_bypass(host):
        '''Return True, if host should be bypassed.

Checks proxy settings gathered from the environment, if specified,
or from the MacOSX framework SystemConfiguration.

'''
        proxies = getproxies_environment()
        if proxies:
            return proxy_bypass_environment(host, proxies)
        return proxy_bypass_macosx_sysconf(host)

    
    def getproxies():
        return getproxies_environment() or getproxies_macosx_sysconf()

if os.name == 'nt':
    
    def getproxies_registry():
        '''Return a dictionary of scheme -> proxy server URL mappings.

Win32 uses the registry to store proxies.

'''
        proxies = { }
        
        try:
            import winreg
        except ImportError:
            return proxies

        
        try:
            internetSettings = winreg.OpenKey(winreg.HKEY_CURRENT_USER, 'Software\\Microsoft\\Windows\\CurrentVersion\\Internet Settings')
            proxyEnable = winreg.QueryValueEx(internetSettings, 'ProxyEnable')[0]
            if proxyEnable:
                proxyServer = str(winreg.QueryValueEx(internetSettings, 'ProxyServer')[0])
                if '=' not in proxyServer and ';' not in proxyServer:
                    proxyServer = 'http={0};https={0};ftp={0}'.format(proxyServer)
                for p in proxyServer.split(';'):
                    protocol, address = p.split('=', 1)
                    if not re.match('(?:[^/:]+)://', address):
                        if protocol in ('http', 'https', 'ftp'):
                            address = 'http://' + address
                        elif protocol == 'socks':
                            address = 'socks://' + address
                    proxies[protocol] = address
                if proxies.get('socks'):
                    address = re.sub('^socks://', 'socks4://', proxies['socks'])
                    proxies['http'] = proxies.get('http') or address
                    proxies['https'] = proxies.get('https') or address
            internetSettings.Close()
        except (OSError, ValueError, TypeError):
            return proxies

        return proxies

    
    def getproxies():
        '''Return a dictionary of scheme -> proxy server URL mappings.

Returns settings gathered from the environment, if specified,
or the registry.

'''
        return getproxies_environment() or getproxies_registry()

    
    def proxy_bypass_registry(host):
        
        try:
            import winreg
        except ImportError:
            return False

        
        try:
            internetSettings = winreg.OpenKey(winreg.HKEY_CURRENT_USER, 'Software\\Microsoft\\Windows\\CurrentVersion\\Internet Settings')
            proxyEnable = winreg.QueryValueEx(internetSettings, 'ProxyEnable')[0]
            proxyOverride = str(winreg.QueryValueEx(internetSettings, 'ProxyOverride')[0])
        except OSError:
            return False

        if not proxyEnable or not proxyOverride:
            return False
        return _proxy_bypass_winreg_override(host, proxyOverride)

    
    def proxy_bypass(host):
        '''Return True, if host should be bypassed.

Checks proxy settings gathered from the environment, if specified,
or the registry.

'''
        proxies = getproxies_environment()
        if proxies:
            return proxy_bypass_environment(host, proxies)
        return proxy_bypass_registry(host)

getproxies = getproxies_environment
proxy_bypass = proxy_bypass_environment


