class ZipFile:
    '''Class with methods to open, read, write, close, list zip files.

z = ZipFile(file, mode="r", compression=ZIP_STORED, allowZip64=True,
            compresslevel=None)

file: Either the path to the file, or a file-like object.
      If it is a path, the file will be opened and closed by ZipFile.
mode: The mode can be either read \'r\', write \'w\', exclusive create \'x\',
      or append \'a\'.
compression: ZIP_STORED (no compression), ZIP_DEFLATED (requires zlib),
      ZIP_BZIP2 (requires bz2), ZIP_LZMA (requires lzma), or
      ZIP_ZSTANDARD (requires compression.zstd).
allowZip64: if True ZipFile will create files with ZIP64 extensions
      when needed, otherwise it will raise an exception when this
      would be necessary.
compresslevel: None (default for the given compression type) or
      an integer specifying the level to pass to the compressor.
      When using ZIP_STORED or ZIP_LZMA this keyword has no effect.
      When using ZIP_DEFLATED integers 0 through 9 are accepted.
      When using ZIP_BZIP2 integers 1 through 9 are accepted.
      When using ZIP_ZSTANDARD integers -7 though 22 are common,
      see the CompressionParameter enum in compression.zstd for
      details.

'''
    fp = None
    _windows_illegal_name_trans_table = None
    _ignore_invalid_names = False
    
    def __init__(self, file, mode = 'r', compression = ZIP_STORED, allowZip64 = True, compresslevel = None, *, strict_timestamps, metadata_encoding):
        """Open the ZIP file with mode read 'r', write 'w', exclusive create
'x', or append 'a'."""
        if mode not in ('r', 'w', 'x', 'a'):
            raise ValueError("ZipFile requires mode 'r', 'w', 'x', or 'a'")
        _check_compression(compression)
        self._allowZip64 = allowZip64
        self._didModify = False
        self.debug = 0
        self.NameToInfo = { }
        self.filelist = []
        self.compression = compression
        self.compresslevel = compresslevel
        self.mode = mode
        self.pwd = None
        self._comment = b''
        self._strict_timestamps = strict_timestamps
        self.metadata_encoding = metadata_encoding
        if self.metadata_encoding and mode != 'r':
            raise ValueError('metadata_encoding is only supported for reading files')
        if isinstance(file, os.PathLike):
            file = os.fspath(file)
        if isinstance(file, str):
            self._filePassed = 0
            self.filename = file
            modeDict = {
                'x+b': 'xb',
                'w+b': 'wb',
                'r+b': 'w+b',
                'a': 'r+b',
                'x': 'x+b',
                'w': 'w+b',
                'r': 'rb' }
            filemode = modeDict[mode]
            
            try:
                self.fp = io.open(file, filemode)
            except OSError:
                if filemode in modeDict:
                    filemode = modeDict[filemode]
                raise

        else:
            self._filePassed = 1
            self.fp = file
            self.filename = getattr(file, 'name', None)
        self._fileRefCnt = 1
        self._lock = threading.RLock()
        self._seekable = True
        self._writing = False
        
        try:
            if mode == 'r':
                self._RealGetContents()
                return None
            if mode in ('w', 'x'):
                self._didModify = True
                
                try:
                    self.start_dir = self.fp.tell()
                except (AttributeError, OSError):
                    self.fp = _Tellable(self.fp)
                    self.start_dir = 0
                    self._seekable = False
                    return None

                
                try:
                    self.fp.seek(self.start_dir)
                except (AttributeError, OSError):
                    self._seekable = False
                    return None

                return None
            if mode == 'a':
                
                try:
                    self._RealGetContents()
                    self.fp.seek(self.start_dir)
                except BadZipFile:
                    self.fp.seek(0, 2)
                    self._didModify = True
                    self.start_dir = self.fp.tell()
                    return None

                return None
            raise ValueError("Mode must be 'r', 'w', 'x', or 'a'")
        except:
            fp = self.fp
            self.fp = None
            self._fpclose(fp)
            raise


    
    def __enter__(self):
        return self

    
    def __exit__(self, type, value, traceback):
        self.close()

    
    def __repr__(self):
        '''<'''
        result = [
            f'''<{self.__class__.__module__!s}.{self.__class__.__qualname__!s}''']
        if self.fp is not None:
            if self._filePassed:
                result.append(' file=%r' % self.fp)
            elif self.filename is not None:
                result.append(' filename=%r' % self.filename)
            result.append(' mode=%r' % self.mode)
        else:
            result.append(' [closed]')
        result.append('>')
        return ''.join(result)

    
    def _RealGetContents(self):
        '''Read in the table of contents for the ZIP file.'''
        fp = self.fp
        
        try:
            endrec = _EndRecData(fp)
        except OSError:
            raise BadZipFile('File is not a zip file')

