class PyZipFile(ZipFile):
    '''Class to create ZIP archives with Python library files and packages.'''
    
    def __init__(self, file, mode = 'r', compression = ZIP_STORED, allowZip64 = True, optimize = -1):
        ZipFile.__init__(self, file, mode = mode, compression = compression, allowZip64 = allowZip64)
        self._optimize = optimize

    
    def writepy(self, pathname, basename = '', filterfunc = None):
        '''Add all files from "pathname" to the ZIP archive.

If pathname is a package directory, search the directory and
all package subdirectories recursively for all *.py and enter
the modules into the archive.  If pathname is a plain
directory, listdir *.py and enter all modules.  Else, pathname
must be a Python *.py file and the module will be put into the
archive.  Added modules are always module.pyc.
This method will compile the module.py into module.pyc if
necessary.
If filterfunc(pathname) is given, it is called with every argument.
When it is False, the file or directory is skipped.
'''
        pathname = os.fspath(pathname)
        if filterfunc and not filterfunc(pathname):
            if self.debug:
                label = 'path' if os.path.isdir(pathname) else 'file'
                print(f'''{label!s} {pathname!r} skipped by filterfunc''')
            return None
        dir, name = os.path.split(pathname)
        if os.path.isdir(pathname):
            initname = os.path.join(pathname, '__init__.py')
            if os.path.isfile(initname):
                if basename:
                    basename = f'''{basename!s}/{name!s}'''
                else:
                    basename = name
                if self.debug:
                    print('Adding package in', pathname, 'as', basename)
                fname, arcname = self._get_codename(initname[0:-3], basename)
                if self.debug:
                    print('Adding', arcname)
                self.write(fname, arcname)
                dirlist = sorted(os.listdir(pathname))
                dirlist.remove('__init__.py')
                for filename in dirlist:
                    path = os.path.join(pathname, filename)
                    root, ext = os.path.splitext(filename)
                    if os.path.isdir(path):
                        if os.path.isfile(os.path.join(path, '__init__.py')):
                            self.writepy(path, basename, filterfunc = filterfunc)
                            continue
                        continue
                    if not ext == '.py':
                        continue
                    if filterfunc and not filterfunc(path):
                        if self.debug:
                            print('file %r skipped by filterfunc' % path)
                        continue
                    fname, arcname = self._get_codename(path[0:-3], basename)
                    if self.debug:
                        print('Adding', arcname)
                    self.write(fname, arcname)
                return None
            if self.debug:
                print('Adding files from directory', pathname)
            for filename in sorted(os.listdir(pathname)):
                path = os.path.join(pathname, filename)
                root, ext = os.path.splitext(filename)
                if not ext == '.py':
                    continue
                if filterfunc and not filterfunc(path):
                    if self.debug:
                        print('file %r skipped by filterfunc' % path)
                    continue
                fname, arcname = self._get_codename(path[0:-3], basename)
                if self.debug:
                    print('Adding', arcname)
                self.write(fname, arcname)
            return None
        if pathname[-3:] != '.py':
            raise RuntimeError('Files added with writepy() must end with ".py"')
        fname, arcname = self._get_codename(pathname[0:-3], basename)
        if self.debug:
            print('Adding file', arcname)
        self.write(fname, arcname)

    
    def _get_codename(self, pathname, basename):
        '''Return (filename, archivename) for the path.

Given a module name path, return the correct file path and
archive name, compiling if necessary.  For example, given
/python/lib/string, return (/python/lib/string.pyc, string).
'''
        
        def _compile(file, optimize = -1):
            import py_compile
            if self.debug:
                print('Compiling', file)
            
            try:
                py_compile.compile(file, doraise = True, optimize = optimize)
            except py_compile.PyCompileError as err:
                print(err.msg)
                return False

            return True

        file_py = pathname + '.py'
        file_pyc = pathname + '.pyc'
        pycache_opt0 = importlib.util.cache_from_source(file_py, optimization = '')
        pycache_opt1 = importlib.util.cache_from_source(file_py, optimization = 1)
        pycache_opt2 = importlib.util.cache_from_source(file_py, optimization = 2)
        if self._optimize == -1:
            if os.path.isfile(file_pyc) and os.stat(file_pyc).st_mtime >= os.stat(file_py).st_mtime:
                arcname = file_pyc
                fname = file_pyc
            elif os.path.isfile(pycache_opt0) and os.stat(pycache_opt0).st_mtime >= os.stat(file_py).st_mtime:
                fname = pycache_opt0
                arcname = file_pyc
            elif os.path.isfile(pycache_opt1) and os.stat(pycache_opt1).st_mtime >= os.stat(file_py).st_mtime:
                fname = pycache_opt1
                arcname = file_pyc
            elif os.path.isfile(pycache_opt2) and os.stat(pycache_opt2).st_mtime >= os.stat(file_py).st_mtime:
                fname = pycache_opt2
                arcname = file_pyc
            elif _compile(file_py):
                if sys.flags.optimize == 0:
                    fname = pycache_opt0
                elif sys.flags.optimize == 1:
                    fname = pycache_opt1
                else:
                    fname = pycache_opt2
                arcname = file_pyc
            else:
                fname = file_py
                arcname = file_py
        elif self._optimize == 0:
            fname = pycache_opt0
            arcname = file_pyc
        else:
            arcname = file_pyc
            if self._optimize == 1:
                fname = pycache_opt1
            elif self._optimize == 2:
                fname = pycache_opt2
            else:
                msg = "invalid value for 'optimize': {!r}".format(self._optimize)
                raise ValueError(msg)
        if (not os.path.isfile(fname) or not (os.stat(fname).st_mtime >= os.stat(file_py).st_mtime)) and not _compile(file_py, optimize = self._optimize):
            fname = file_py
            arcname = file_py
        archivename = os.path.split(arcname)[1]
        if basename:
            archivename = f'''{basename!s}/{archivename!s}'''
        return (fname, archivename)



def main(args = None):
    import argparse
    description = 'A simple command-line interface for zipfile module.'
    parser = argparse.ArgumentParser(description = description, color = True)
    group = parser.add_mutually_exclusive_group(required = True)
    group.add_argument('-l', '--list', metavar = '<zipfile>', help = 'Show listing of a zipfile')
    group.add_argument('-e', '--extract', nargs = 2, metavar = ('<zipfile>', '<output_dir>'), help = 'Extract zipfile into target dir')
    group.add_argument('-c', '--create', nargs = '+', metavar = ('<name>', '<file>'), help = 'Create zipfile from sources')
    group.add_argument('-t', '--test', metavar = '<zipfile>', help = 'Test if a zipfile is valid')
    parser.add_argument('--metadata-encoding', metavar = '<encoding>', help = 'Specify encoding of member names for -l, -e and -t')
    args = parser.parse_args(args)
    encoding = args.metadata_encoding
    if args.test is not None:
        src = args.test
        with ZipFile(src, 'r', metadata_encoding = encoding) as zf:
            badfile = zf.testzip()
        if badfile:
            print('The following enclosed file is corrupted: {!r}'.format(badfile))
        print('Done testing')
        return None
    if args.list is not None:
        src = args.list
        with ZipFile(src, 'r', metadata_encoding = encoding) as zf:
            zf.printdir()
        return None
    if args.extract is not None:
        src, curdir = args.extract
        with ZipFile(src, 'r', metadata_encoding = encoding) as zf:
            zf.extractall(curdir)
        return None
    if args.create is not None:
        if encoding:
            print('Non-conforming encodings not supported with -c.', file = sys.stderr)
            sys.exit(1)
        zip_name = args.create.pop(0)
        files = args.create
        
        def addToZip(zf, path, zippath):
            if os.path.isfile(path):
                zf.write(path, zippath, ZIP_DEFLATED)
                return None
            if os.path.isdir(path):
                if zippath:
                    zf.write(path, zippath)
                for nm in sorted(os.listdir(path)):
                    addToZip(zf, os.path.join(path, nm), os.path.join(zippath, nm))
                return None

        with ZipFile(zip_name, 'w') as zf:
            for path in files:
                zippath = os.path.basename(path)
                if not zippath:
                    zippath = os.path.basename(os.path.dirname(path))
                if zippath in ('', os.curdir, os.pardir):
                    zippath = ''
                addToZip(zf, path, zippath)
        return None

